content:
/* 隐藏导航栏菜单项的下拉箭头 */
#nav .menus_items .site-page.has-dropdown::after {
    display: none !important;
}

#web_bg {
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important; /* 核心属性：让背景固定，不随滚动条移动 */
  background-position: center !important;
}

#post {
    /* 1. 宽度调整 */
    /* 修复了之前的拼写错误 (widht -> width) */
    max-width: 12000px !important; /* 建议不要超过屏幕宽度的80%，否则阅读体验不好 */
    width: 90% !important;        /* 在小屏幕上保持边距 */

    /* 2. 透明度与背景调整 */
    /* 0.85 代表 85% 的不透明度，看起来是纯白偏透，没有模糊感 */
    background: rgba(255, 255, 255, 0.85) !important;

    /* 3. 彻底移除毛玻璃效果 */
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;

    /* 4. 保持圆角和间距 */
    border-radius: 16px !important;
    padding: 50px !important;
    margin: 30px auto !important;
}

.note {
    border-radius: 12px !important;
    /* 不强制覆盖 background，只增加一点通透感 */
    /* 利用 mix-blend-mode 或者降低不透明度来融合背景 */
    opacity: 0.85 !important; /* 整体稍微透明一点点 */
}

/* 文章正文默认字号 */
#article-container {
  font-size: 18px;
  line-height: 1.8;
}

/* 移动端字号 */
@media screen and (max-width: 768px) {
  #article-container {
    font-size: 16px;
    line-height: 1.75;
  }
}
/* 全站动态视频背景 */
#video-background {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  z-index: -999;
  pointer-events: none;
}

/* 禁用 Butterfly 原来的背景层 */
#web_bg {
  background: transparent !important;
}

@media screen and (max-width: 768px),
       (prefers-reduced-motion: reduce) {
  #video-background {
    display: none !important;
  }
/* 为手机和减少动画模式保留静态背景 */
  #web_bg {
    background:
      url("/images/mainpage.jpg")
      center / cover no-repeat fixed !important;
  }

  body::before {
    display: none;
  }
}
